    box.innerHTML = !items.length ? '<div class="empty">Не нашёл продуктов в базах — Нутрициолог посчитает сам</div><button class="btn txsave" id="txSave">Записать</button>' : `<div class="card" style="margin:14px 0 0;padding:4px 14px">${items.map((x, i) => `<div class="txrow" data-i="${i}"><div class="txin"><div class="sp"><b style="font-size:14px">${esc(x.name)}</b>${x.kcal == null || x.confidence < .7 ? ' <span class="txest"><i></i>уточняется</span>' : ''}
      <div class="txm">${x.kcal == null ? '<span class="txnf">Отправим Нутрициологу</span>' : `${r0(x.kcal)} ккал · Б ${r1(x.p)} · Ж ${r1(x.f)} · У ${r1(x.c)}`}<br><span style="opacity:.75">${esc(x.source)}</span></div></div>
      ${x.kcal != null ? `<div class="txg"><button type="button" data-d="-10">−</button><input inputmode="decimal" value="${r0(x.grams)}" data-g="${i}"><span>г</span><button type="button" data-d="10">+</button></div>` : ''}</div></div>`).join('')}</div>
      <div class="row" style="justify-content:space-between;margin:12px 4px"><span class="mut">Итого в «${MNAME[CUR_MEAL]}»</span><b>${r0(T.k)} ккал · Б ${r0(T.p)} · Ж ${r0(T.f)} · У ${r0(T.c)}</b></div>
      <button class="btn txsave" id="txSave">Записать</button><p class="mut" style="text-align:center;margin-top:8px">Смахните строку влево, чтобы удалить</p>`;
